CREATE SCHEMA IF NOT EXISTS app_private;
REVOKE ALL ON SCHEMA app_private FROM PUBLIC,anon;
GRANT USAGE ON SCHEMA app_private TO authenticated,service_role;

CREATE OR REPLACE FUNCTION app_private.user_is_donor_for_org(_user_id uuid,_org_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.donor_accounts da WHERE da.user_id=_user_id AND da.organization_id=_org_id AND da.is_active) $$;
CREATE OR REPLACE FUNCTION app_private.case_is_visible_scoped(_user_id uuid,_case_id uuid,_org_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,app_private AS $$ SELECT EXISTS(SELECT 1 FROM public.beneficiary_cases c WHERE c.id=_case_id AND c.organization_id=_org_id AND c.deleted_at IS NULL AND public.user_belongs_to_org(_user_id,_org_id) AND NOT app_private.user_is_donor_for_org(_user_id,_org_id) AND (NOT c.is_sensitive OR public.user_is_org_elevated(_user_id,_org_id) OR public.user_has_permission(_user_id,_org_id,'cases','view','sensitive')) AND (public.user_is_org_elevated(_user_id,_org_id) OR (NOT public.user_is_field_scoped(_user_id,_org_id) AND NOT public.user_is_program_scoped(_user_id,_org_id)) OR (public.user_is_program_scoped(_user_id,_org_id) AND c.program_id IN (SELECT public.user_assigned_program_ids(_user_id,_org_id))) OR (public.user_is_field_scoped(_user_id,_org_id) AND (c.assigned_to=_user_id OR c.created_by=_user_id OR public.beneficiary_visible_scoped(_user_id,c.beneficiary_id,_org_id)))) ) $$;
CREATE OR REPLACE FUNCTION app_private.staff_task_is_visible_scoped(_user_id uuid,_task_id uuid,_org_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,app_private AS $$ SELECT EXISTS(SELECT 1 FROM public.staff_tasks t WHERE t.id=_task_id AND t.organization_id=_org_id AND public.user_belongs_to_org(_user_id,_org_id) AND NOT app_private.user_is_donor_for_org(_user_id,_org_id) AND (NOT t.is_sensitive OR public.user_is_org_elevated(_user_id,_org_id) OR public.user_has_permission(_user_id,_org_id,'cases','view','sensitive')) AND (t.case_id IS NULL OR app_private.case_is_visible_scoped(_user_id,t.case_id,_org_id)) AND (public.user_is_org_elevated(_user_id,_org_id) OR (NOT public.user_is_field_scoped(_user_id,_org_id) AND NOT public.user_is_program_scoped(_user_id,_org_id)) OR (public.user_is_program_scoped(_user_id,_org_id) AND (t.program_id IN (SELECT public.user_assigned_program_ids(_user_id,_org_id)) OR EXISTS(SELECT 1 FROM public.beneficiary_cases c WHERE c.id=t.case_id AND c.program_id IN (SELECT public.user_assigned_program_ids(_user_id,_org_id))))) OR (public.user_is_field_scoped(_user_id,_org_id) AND (t.assigned_to=_user_id OR t.assigned_by=_user_id OR (t.case_id IS NOT NULL AND app_private.case_is_visible_scoped(_user_id,t.case_id,_org_id))))) ) $$;
CREATE OR REPLACE FUNCTION app_private.work_management_source_org(_type text,_id uuid,_org uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ok boolean:=false; BEGIN CASE _type WHEN 'life_event' THEN SELECT EXISTS(SELECT 1 FROM public.life_events WHERE id=_id AND organization_id=_org AND deleted_at IS NULL) INTO ok; WHEN 'vulnerability_assessment' THEN SELECT EXISTS(SELECT 1 FROM public.vulnerability_assessments WHERE id=_id AND organization_id=_org) INTO ok; WHEN 'need' THEN SELECT EXISTS(SELECT 1 FROM public.beneficiary_needs WHERE id=_id AND organization_id=_org) INTO ok; WHEN 'home_visit' THEN SELECT EXISTS(SELECT 1 FROM public.home_visits WHERE id=_id AND organization_id=_org AND deleted_at IS NULL) INTO ok; WHEN 'school_visit' THEN SELECT EXISTS(SELECT 1 FROM public.school_visits WHERE id=_id AND organization_id=_org AND deleted_at IS NULL) INTO ok; WHEN 'donor_request' THEN SELECT EXISTS(SELECT 1 FROM public.donation_intents WHERE id=_id AND organization_id=_org) INTO ok; ELSE RAISE EXCEPTION 'Unsupported task source type'; END CASE; RETURN ok; END $$;

CREATE OR REPLACE FUNCTION app_private.validate_staff_task_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,app_private AS $$ DECLARE co uuid; cs boolean; ss boolean:=false; rs boolean:=false; sens text; manage boolean; BEGIN manage:=auth.role()='service_role' OR public.user_is_org_elevated(auth.uid(),NEW.organization_id) OR public.user_has_permission(auth.uid(),NEW.organization_id,'tasks','manage','tasks'); IF TG_OP='UPDATE' THEN IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN RAISE EXCEPTION 'Task organisation cannot change'; END IF; IF (NEW.source_event_type,NEW.source_record_type,NEW.source_record_id) IS DISTINCT FROM (OLD.source_event_type,OLD.source_record_type,OLD.source_record_id) THEN RAISE EXCEPTION 'Task source key is immutable'; END IF; IF NOT manage AND OLD.assigned_to=auth.uid() THEN IF (to_jsonb(NEW)-ARRAY['status','completed_at','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','completed_at','updated_at']) THEN RAISE EXCEPTION 'Assigned staff may only progress their task'; END IF; ELSIF NOT manage THEN RAISE EXCEPTION 'Not authorised to edit this task'; END IF; IF NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='todo' AND NEW.status IN ('in_progress','cancelled')) OR (OLD.status='in_progress' AND NEW.status IN ('todo','blocked','completed','cancelled')) OR (OLD.status='blocked' AND NEW.status IN ('in_progress','cancelled'))) THEN RAISE EXCEPTION 'Invalid task status transition: % to %',OLD.status,NEW.status; END IF; ELSIF auth.role()<>'service_role' AND NOT manage THEN RAISE EXCEPTION 'Task management permission required'; END IF; IF NEW.assigned_to IS NOT NULL AND NOT public.user_belongs_to_org(NEW.assigned_to,NEW.organization_id) THEN RAISE EXCEPTION 'Assignee must belong to task organisation'; END IF; IF NEW.case_id IS NOT NULL THEN SELECT organization_id,is_sensitive INTO co,cs FROM public.beneficiary_cases WHERE id=NEW.case_id AND deleted_at IS NULL; IF co IS DISTINCT FROM NEW.organization_id THEN RAISE EXCEPTION 'Linked case must belong to the same organisation'; END IF; NEW.is_sensitive:=NEW.is_sensitive OR COALESCE(cs,false); IF auth.role()<>'service_role' AND NOT app_private.case_is_visible_scoped(auth.uid(),NEW.case_id,NEW.organization_id) THEN RAISE EXCEPTION 'Linked case is outside your access scope'; END IF; END IF; IF NEW.related_record_id IS NOT NULL AND NOT app_private.work_management_source_org(NEW.related_record_type,NEW.related_record_id,NEW.organization_id) THEN RAISE EXCEPTION 'Linked record must exist in the same organisation'; END IF; IF NEW.source_record_id IS NOT NULL AND NOT app_private.work_management_source_org(NEW.source_record_type,NEW.source_record_id,NEW.organization_id) THEN RAISE EXCEPTION 'Task source must exist in the same organisation'; END IF; IF NEW.related_record_type='life_event' THEN SELECT is_sensitive INTO rs FROM public.life_events WHERE id=NEW.related_record_id AND organization_id=NEW.organization_id; ELSIF NEW.related_record_type='vulnerability_assessment' THEN SELECT sensitivity<>'standard' INTO rs FROM public.vulnerability_assessments WHERE id=NEW.related_record_id AND organization_id=NEW.organization_id; END IF; IF NEW.source_record_type='life_event' THEN SELECT is_sensitive INTO ss FROM public.life_events WHERE id=NEW.source_record_id AND organization_id=NEW.organization_id; ELSIF NEW.source_record_type='vulnerability_assessment' THEN SELECT sensitivity<>'standard' INTO ss FROM public.vulnerability_assessments WHERE id=NEW.source_record_id AND organization_id=NEW.organization_id; END IF; NEW.is_sensitive:=NEW.is_sensitive OR COALESCE(rs,false) OR COALESCE(ss,false); IF NEW.is_sensitive AND auth.role()<>'service_role' AND NOT (public.user_is_org_elevated(auth.uid(),NEW.organization_id) OR public.user_has_permission(auth.uid(),NEW.organization_id,'cases','view','sensitive')) THEN RAISE EXCEPTION 'Sensitive work permission required'; END IF; IF NEW.status='completed' THEN NEW.completed_at:=COALESCE(NEW.completed_at,now()); ELSE NEW.completed_at:=NULL; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION app_private.validate_beneficiary_case_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE manage boolean; BEGIN manage:=auth.role()='service_role' OR public.user_is_org_elevated(auth.uid(),NEW.organization_id) OR public.user_has_permission(auth.uid(),NEW.organization_id,'cases','manage','cases'); IF TG_OP='INSERT' THEN IF auth.role()<>'service_role' AND NOT manage THEN RAISE EXCEPTION 'Case management permission required'; END IF; ELSE IF NEW.organization_id IS DISTINCT FROM OLD.organization_id OR NEW.beneficiary_id IS DISTINCT FROM OLD.beneficiary_id THEN RAISE EXCEPTION 'Case organisation and beneficiary cannot change'; END IF; IF NOT manage AND OLD.assigned_to=auth.uid() THEN IF (to_jsonb(NEW)-ARRAY['case_status','closed_date','closure_reason','updated_by','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['case_status','closed_date','closure_reason','updated_by','updated_at']) THEN RAISE EXCEPTION 'Assigned staff may only progress or close their case'; END IF; ELSIF NOT manage THEN RAISE EXCEPTION 'Not authorised to edit this case'; END IF; IF NEW.case_status IS DISTINCT FROM OLD.case_status AND NOT ((OLD.case_status='open' AND NEW.case_status IN ('in_progress','referred','resolved','closed','lost_to_follow_up')) OR (OLD.case_status='in_progress' AND NEW.case_status IN ('open','referred','resolved','closed','lost_to_follow_up')) OR (OLD.case_status='referred' AND NEW.case_status IN ('in_progress','resolved','closed','lost_to_follow_up')) OR (OLD.case_status='resolved' AND NEW.case_status IN ('in_progress','closed'))) THEN RAISE EXCEPTION 'Invalid case status transition: % to %',OLD.case_status,NEW.case_status; END IF; END IF; IF NEW.assigned_to IS NOT NULL AND NOT public.user_belongs_to_org(NEW.assigned_to,NEW.organization_id) THEN RAISE EXCEPTION 'Case assignee must belong to case organisation'; END IF; IF NEW.case_status IN ('resolved','closed','lost_to_follow_up') THEN IF NULLIF(btrim(NEW.closure_reason),'') IS NULL THEN RAISE EXCEPTION 'A reason is required to close or resolve a case'; END IF; NEW.closed_date:=COALESCE(NEW.closed_date,CURRENT_DATE); ELSE NEW.closed_date:=NULL; NEW.closure_reason:=NULL; END IF; IF NEW.is_sensitive AND auth.role()<>'service_role' AND NOT (public.user_is_org_elevated(auth.uid(),NEW.organization_id) OR public.user_has_permission(auth.uid(),NEW.organization_id,'cases','view','sensitive')) THEN RAISE EXCEPTION 'Sensitive case permission required'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION app_private.validate_case_entry_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,app_private AS $$ DECLARE co uuid; ben uuid; BEGIN SELECT organization_id,beneficiary_id INTO co,ben FROM public.beneficiary_cases WHERE id=NEW.case_id AND deleted_at IS NULL; IF co IS DISTINCT FROM NEW.organization_id OR ben IS DISTINCT FROM NEW.beneficiary_id THEN RAISE EXCEPTION 'Entry must match case organisation and beneficiary'; END IF; IF auth.role()<>'service_role' AND NOT app_private.case_is_visible_scoped(auth.uid(),NEW.case_id,NEW.organization_id) THEN RAISE EXCEPTION 'Case is outside your access scope'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION app_private.audit_work_management_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE typ text; ev text; oldj jsonb; newj jsonb; BEGIN typ:=CASE WHEN TG_TABLE_NAME='staff_tasks' THEN 'staff_task' ELSE 'beneficiary_case' END; IF TG_OP<>'INSERT' THEN oldj:=to_jsonb(OLD); END IF; IF TG_OP<>'DELETE' THEN newj:=to_jsonb(NEW); END IF; ev:=typ||CASE WHEN TG_OP='INSERT' THEN '_created' WHEN TG_OP='DELETE' THEN '_deleted' ELSE '_updated' END; INSERT INTO public.audit_logs(event_type,entity_type,entity_id,user_id,old_values,new_values,metadata) VALUES(ev,typ,COALESCE(NEW.id,OLD.id),auth.uid(),CASE WHEN oldj IS NULL THEN NULL ELSE jsonb_build_object('status',COALESCE(oldj->>'status',oldj->>'case_status'),'assigned_to',oldj->>'assigned_to','priority',oldj->>'priority') END,CASE WHEN newj IS NULL THEN NULL ELSE jsonb_build_object('status',COALESCE(newj->>'status',newj->>'case_status'),'assigned_to',newj->>'assigned_to','priority',newj->>'priority') END,jsonb_build_object('organization_id',COALESCE(newj->>'organization_id',oldj->>'organization_id'),'case_id',newj->>'case_id','source_event_type',newj->>'source_event_type')); RETURN COALESCE(NEW,OLD); END $$;
CREATE OR REPLACE FUNCTION app_private.notify_work_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE assignee uuid; org uuid; ident uuid; kind text; BEGIN assignee:=NEW.assigned_to; org:=NEW.organization_id; ident:=NEW.id; kind:=CASE WHEN TG_TABLE_NAME='staff_tasks' THEN 'task' ELSE 'case' END; IF assignee IS NOT NULL AND (TG_OP='INSERT' OR NEW.assigned_to IS DISTINCT FROM OLD.assigned_to) AND assignee IS DISTINCT FROM auth.uid() THEN INSERT INTO public.notifications(organization_id,user_id,title,message,category,severity,related_entity_type,related_entity_id,metadata) VALUES(org,assignee,'Work assigned to you','Please review your assigned '||kind||'.','work_management','info',kind,ident,jsonb_build_object('organization_id',org)); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION app_private.create_or_get_source_task(_org uuid,_event text,_type text,_record uuid,_title text,_description text,_assignee uuid,_priority text,_due date,_program uuid,_project uuid,_case uuid,_sensitive boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,app_private AS $$ DECLARE ident uuid; sensitive_value boolean:=COALESCE(_sensitive,false); BEGIN IF NULLIF(btrim(_event),'') IS NULL OR _record IS NULL OR NULLIF(btrim(_title),'') IS NULL THEN RAISE EXCEPTION 'Event type, source record and title are required'; END IF; IF auth.role()<>'service_role' AND (NOT public.user_belongs_to_org(auth.uid(),_org) OR app_private.user_is_donor_for_org(auth.uid(),_org) OR NOT (public.user_is_org_elevated(auth.uid(),_org) OR public.user_has_permission(auth.uid(),_org,'tasks','manage','tasks'))) THEN RAISE EXCEPTION 'Task management permission required'; END IF; IF NOT app_private.work_management_source_org(_type,_record,_org) THEN RAISE EXCEPTION 'Source record not found in this organisation'; END IF; IF _type='life_event' THEN SELECT sensitive_value OR is_sensitive INTO sensitive_value FROM public.life_events WHERE id=_record AND organization_id=_org; ELSIF _type='vulnerability_assessment' THEN SELECT sensitive_value OR (sensitivity<>'standard') INTO sensitive_value FROM public.vulnerability_assessments WHERE id=_record AND organization_id=_org; END IF; IF sensitive_value AND auth.role()<>'service_role' AND NOT (public.user_is_org_elevated(auth.uid(),_org) OR public.user_has_permission(auth.uid(),_org,'cases','view','sensitive')) THEN RAISE EXCEPTION 'Sensitive work permission required'; END IF; INSERT INTO public.staff_tasks(organization_id,title,description,assigned_to,assigned_by,priority,due_date,program_id,project_id,case_id,related_record_type,related_record_id,source_event_type,source_record_type,source_record_id,is_sensitive) VALUES(_org,_title,_description,_assignee,auth.uid(),_priority,_due,_program,_project,_case,_type,_record,_event,_type,_record,sensitive_value) ON CONFLICT(organization_id,source_event_type,source_record_id) WHERE source_event_type IS NOT NULL AND source_record_id IS NOT NULL DO NOTHING; SELECT id INTO ident FROM public.staff_tasks WHERE organization_id=_org AND source_event_type=_event AND source_record_id=_record; RETURN ident; END $$;
CREATE OR REPLACE FUNCTION app_private.get_staff_task_workload(_org uuid) RETURNS TABLE(staff_user_id uuid,open_tasks bigint,overdue_tasks bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,app_private AS $$ BEGIN IF NOT public.user_belongs_to_org(auth.uid(),_org) OR app_private.user_is_donor_for_org(auth.uid(),_org) THEN RAISE EXCEPTION 'Not authorised'; END IF; IF NOT (public.user_is_org_elevated(auth.uid(),_org) OR public.user_has_permission(auth.uid(),_org,'tasks','manage','tasks') OR public.user_has_permission(auth.uid(),_org,'hr','view','staff')) THEN RETURN QUERY SELECT t.assigned_to,count(*) FILTER(WHERE t.status NOT IN ('completed','cancelled'))::bigint,count(*) FILTER(WHERE t.status NOT IN ('completed','cancelled') AND t.due_date<CURRENT_DATE)::bigint FROM public.staff_tasks t WHERE t.organization_id=_org AND t.assigned_to=auth.uid() GROUP BY t.assigned_to; ELSE RETURN QUERY SELECT t.assigned_to,count(*) FILTER(WHERE t.status NOT IN ('completed','cancelled'))::bigint,count(*) FILTER(WHERE t.status NOT IN ('completed','cancelled') AND app_private.staff_task_is_visible_scoped(auth.uid(),t.id,_org))::bigint FROM public.staff_tasks t WHERE t.organization_id=_org AND t.assigned_to IS NOT NULL AND app_private.staff_task_is_visible_scoped(auth.uid(),t.id,_org) GROUP BY t.assigned_to; END IF; END $$;

DROP POLICY IF EXISTS staff_tasks_scoped_insert ON public.staff_tasks; DROP POLICY IF EXISTS staff_tasks_scoped_select ON public.staff_tasks; DROP POLICY IF EXISTS staff_tasks_scoped_update ON public.staff_tasks;
DROP POLICY IF EXISTS beneficiary_cases_scoped_insert ON public.beneficiary_cases; DROP POLICY IF EXISTS beneficiary_cases_scoped_select ON public.beneficiary_cases; DROP POLICY IF EXISTS beneficiary_cases_scoped_update ON public.beneficiary_cases;
DROP POLICY IF EXISTS case_entries_scoped_select ON public.case_entries; DROP POLICY IF EXISTS case_entries_scoped_insert ON public.case_entries; DROP POLICY IF EXISTS case_entries_scoped_update ON public.case_entries;
CREATE POLICY staff_tasks_scoped_insert ON public.staff_tasks FOR INSERT TO authenticated WITH CHECK(public.user_belongs_to_org(auth.uid(),organization_id) AND NOT app_private.user_is_donor_for_org(auth.uid(),organization_id) AND (public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'tasks','manage','tasks')));
CREATE POLICY staff_tasks_scoped_select ON public.staff_tasks FOR SELECT TO authenticated USING(app_private.staff_task_is_visible_scoped(auth.uid(),id,organization_id) AND (public.user_has_permission(auth.uid(),organization_id,'tasks','view','tasks') OR public.user_has_permission(auth.uid(),organization_id,'tasks','manage','tasks') OR assigned_to=auth.uid()));
CREATE POLICY staff_tasks_scoped_update ON public.staff_tasks FOR UPDATE TO authenticated USING(app_private.staff_task_is_visible_scoped(auth.uid(),id,organization_id) AND (public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'tasks','manage','tasks') OR assigned_to=auth.uid())) WITH CHECK(app_private.staff_task_is_visible_scoped(auth.uid(),id,organization_id) AND (public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'tasks','manage','tasks') OR assigned_to=auth.uid()));
CREATE POLICY beneficiary_cases_scoped_insert ON public.beneficiary_cases FOR INSERT TO authenticated WITH CHECK(public.user_belongs_to_org(auth.uid(),organization_id) AND NOT app_private.user_is_donor_for_org(auth.uid(),organization_id) AND (public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'cases','manage','cases')) AND (NOT is_sensitive OR public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'cases','view','sensitive')));
CREATE POLICY beneficiary_cases_scoped_select ON public.beneficiary_cases FOR SELECT TO authenticated USING(app_private.case_is_visible_scoped(auth.uid(),id,organization_id) AND public.user_has_permission(auth.uid(),organization_id,'cases','view','cases'));
CREATE POLICY beneficiary_cases_scoped_update ON public.beneficiary_cases FOR UPDATE TO authenticated USING(app_private.case_is_visible_scoped(auth.uid(),id,organization_id) AND (public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'cases','manage','cases') OR assigned_to=auth.uid())) WITH CHECK(app_private.case_is_visible_scoped(auth.uid(),id,organization_id) AND (public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'cases','manage','cases') OR assigned_to=auth.uid()));
CREATE POLICY case_entries_scoped_select ON public.case_entries FOR SELECT TO authenticated USING(app_private.case_is_visible_scoped(auth.uid(),case_id,organization_id) AND public.user_has_permission(auth.uid(),organization_id,'cases','view','cases'));
CREATE POLICY case_entries_scoped_insert ON public.case_entries FOR INSERT TO authenticated WITH CHECK(app_private.case_is_visible_scoped(auth.uid(),case_id,organization_id) AND (public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'cases','manage','cases') OR EXISTS(SELECT 1 FROM public.beneficiary_cases c WHERE c.id=case_id AND c.assigned_to=auth.uid())));
CREATE POLICY case_entries_scoped_update ON public.case_entries FOR UPDATE TO authenticated USING(app_private.case_is_visible_scoped(auth.uid(),case_id,organization_id) AND (public.user_is_org_elevated(auth.uid(),organization_id) OR public.user_has_permission(auth.uid(),organization_id,'cases','manage','cases') OR EXISTS(SELECT 1 FROM public.beneficiary_cases c WHERE c.id=case_id AND c.assigned_to=auth.uid()))) WITH CHECK(app_private.case_is_visible_scoped(auth.uid(),case_id,organization_id));

DROP TRIGGER IF EXISTS validate_staff_task_write ON public.staff_tasks; CREATE TRIGGER validate_staff_task_write BEFORE INSERT OR UPDATE ON public.staff_tasks FOR EACH ROW EXECUTE FUNCTION app_private.validate_staff_task_write();
DROP TRIGGER IF EXISTS validate_beneficiary_case_write ON public.beneficiary_cases; CREATE TRIGGER validate_beneficiary_case_write BEFORE INSERT OR UPDATE ON public.beneficiary_cases FOR EACH ROW EXECUTE FUNCTION app_private.validate_beneficiary_case_write();
DROP TRIGGER IF EXISTS validate_case_entry_access ON public.case_entries; CREATE TRIGGER validate_case_entry_access BEFORE INSERT OR UPDATE ON public.case_entries FOR EACH ROW EXECUTE FUNCTION app_private.validate_case_entry_access();
DROP TRIGGER IF EXISTS audit_staff_tasks_changes ON public.staff_tasks; CREATE TRIGGER audit_staff_tasks_changes AFTER INSERT OR UPDATE ON public.staff_tasks FOR EACH ROW EXECUTE FUNCTION app_private.audit_work_management_change();
DROP TRIGGER IF EXISTS audit_beneficiary_cases_changes ON public.beneficiary_cases; CREATE TRIGGER audit_beneficiary_cases_changes AFTER INSERT OR UPDATE ON public.beneficiary_cases FOR EACH ROW EXECUTE FUNCTION app_private.audit_work_management_change();
DROP TRIGGER IF EXISTS notify_task_assignee ON public.staff_tasks; CREATE TRIGGER notify_task_assignee AFTER INSERT OR UPDATE OF assigned_to ON public.staff_tasks FOR EACH ROW EXECUTE FUNCTION app_private.notify_work_assignment();
DROP TRIGGER IF EXISTS notify_case_assignee ON public.beneficiary_cases; CREATE TRIGGER notify_case_assignee AFTER INSERT OR UPDATE OF assigned_to ON public.beneficiary_cases FOR EACH ROW EXECUTE FUNCTION app_private.notify_work_assignment();

DROP FUNCTION IF EXISTS public.user_is_donor_for_org(uuid,uuid); DROP FUNCTION IF EXISTS public.case_is_visible_scoped(uuid,uuid,uuid); DROP FUNCTION IF EXISTS public.staff_task_is_visible_scoped(uuid,uuid,uuid); DROP FUNCTION IF EXISTS public.work_management_source_org(text,uuid,uuid); DROP FUNCTION IF EXISTS public.validate_staff_task_write(); DROP FUNCTION IF EXISTS public.validate_beneficiary_case_write(); DROP FUNCTION IF EXISTS public.validate_case_entry_access(); DROP FUNCTION IF EXISTS public.audit_work_management_change(); DROP FUNCTION IF EXISTS public.notify_work_assignment(); DROP FUNCTION IF EXISTS public.create_or_get_source_task(uuid,text,text,uuid,text,text,uuid,text,date,uuid,uuid,uuid,boolean); DROP FUNCTION IF EXISTS public.get_staff_task_workload(uuid);
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app_private FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION app_private.user_is_donor_for_org(uuid,uuid),app_private.case_is_visible_scoped(uuid,uuid,uuid),app_private.staff_task_is_visible_scoped(uuid,uuid,uuid),app_private.work_management_source_org(text,uuid,uuid),app_private.validate_staff_task_write(),app_private.validate_beneficiary_case_write(),app_private.validate_case_entry_access(),app_private.audit_work_management_change(),app_private.notify_work_assignment(),app_private.create_or_get_source_task(uuid,text,text,uuid,text,text,uuid,text,date,uuid,uuid,uuid,boolean),app_private.get_staff_task_workload(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.create_or_get_source_task(_org_id uuid,_event_type text,_source_record_type text,_source_record_id uuid,_title text,_description text DEFAULT NULL,_assigned_to uuid DEFAULT NULL,_priority text DEFAULT 'medium',_due_date date DEFAULT NULL,_program_id uuid DEFAULT NULL,_project_id uuid DEFAULT NULL,_case_id uuid DEFAULT NULL,_is_sensitive boolean DEFAULT false) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public,app_private AS $$ SELECT app_private.create_or_get_source_task(_org_id,_event_type,_source_record_type,_source_record_id,_title,_description,_assigned_to,_priority,_due_date,_program_id,_project_id,_case_id,_is_sensitive) $$;
CREATE OR REPLACE FUNCTION public.get_staff_task_workload(_org_id uuid) RETURNS TABLE(staff_user_id uuid,open_tasks bigint,overdue_tasks bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,app_private AS $$ SELECT * FROM app_private.get_staff_task_workload(_org_id) $$;
REVOKE ALL ON FUNCTION public.create_or_get_source_task(uuid,text,text,uuid,text,text,uuid,text,date,uuid,uuid,uuid,boolean),public.get_staff_task_workload(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_or_get_source_task(uuid,text,text,uuid,text,text,uuid,text,date,uuid,uuid,uuid,boolean),public.get_staff_task_workload(uuid) TO authenticated,service_role;
